#include <iostream>
#include <cassert>
#include <cmath>
#include "math_parser.h"
#include "programmer_mode.h"

void testOperatorReplacement() {
    std::cout << "[Test] Operator Replacement..." << std::endl;

    // Test 1: Typing 5, then +, then *
    std::string s = "5";
    s = calc::MathParser::handleOperatorInput(s, "+");
    assert(s == "5 + ");

    // User changes mind and presses *
    s = calc::MathParser::handleOperatorInput(s, "*");
    assert(s == "5 * ");

    // User types 3
    s += "3";
    calc::MathParser parser;
    auto res = parser.evaluate(s);
    assert(res.success);
    assert(std::abs(res.value - 15.0) < 1e-9);

    // Test 2: Unary minus after *
    s = "5 * ";
    s = calc::MathParser::handleOperatorInput(s, "-");
    assert(s == "5 * -");
    s += "2";
    res = parser.evaluate(s);
    assert(res.success);
    assert(std::abs(res.value - (-10.0)) < 1e-9);

    std::cout << "  ✓ Passed!" << std::endl;
}

void testTrailingOperatorAndParens() {
    std::cout << "[Test] Trailing Operators and Unclosed Parens..." << std::endl;

    calc::MathParser parser;

    // Trailing operator: "10 + 20 + " should evaluate to 30
    auto res = parser.evaluate("10 + 20 + ");
    assert(res.success);
    assert(std::abs(res.value - 30.0) < 1e-9);

    // Unclosed parentheses: "sin(30" in Degrees mode -> 0.5
    res = parser.evaluate("sin(30");
    assert(res.success);
    assert(std::abs(res.value - 0.5) < 1e-9);

    // Nested unclosed parens: "(2 + 3 * (4 + 1" -> (2 + 3 * 5) = 17
    res = parser.evaluate("(2 + 3 * (4 + 1");
    assert(res.success);
    assert(std::abs(res.value - 17.0) < 1e-9);

    std::cout << "  ✓ Passed!" << std::endl;
}

void testAdvancedMath() {
    std::cout << "[Test] Scientific Functions & Constants..." << std::endl;

    calc::MathParser parser;

    // Factorial: 5! = 120
    auto res = parser.evaluate("5!");
    assert(res.success);
    assert(std::abs(res.value - 120.0) < 1e-9);

    // Combinations: nCr(5, 2) = 10
    res = parser.evaluate("ncr(5, 2)");
    assert(res.success);
    assert(std::abs(res.value - 10.0) < 1e-9);

    // Powers & roots
    res = parser.evaluate("2^8");
    assert(res.success);
    assert(std::abs(res.value - 256.0) < 1e-9);

    res = parser.evaluate("sqrt(144)");
    assert(res.success);
    assert(std::abs(res.value - 12.0) < 1e-9);

    // Quick reciprocal: 1/4 = 0.25
    res = parser.evaluate("1/4");
    assert(res.success);
    assert(std::abs(res.value - 0.25) < 1e-9);

    // Reciprocal trig: sec(60 deg) = 1/cos(60 deg) = 1 / 0.5 = 2
    res = parser.evaluate("sec(60)");
    assert(res.success);
    assert(std::abs(res.value - 2.0) < 1e-9);

    // cosec(30 deg) = 1/sin(30 deg) = 1 / 0.5 = 2
    res = parser.evaluate("cosec(30)");
    assert(res.success);
    assert(std::abs(res.value - 2.0) < 1e-9);

    // cot(45 deg) = 1
    res = parser.evaluate("cot(45)");
    assert(res.success);
    assert(std::abs(res.value - 1.0) < 1e-9);

    // Inverse trig: asec(2) = 60 deg
    res = parser.evaluate("asec(2)");
    assert(res.success);
    assert(std::abs(res.value - 60.0) < 1e-9);

    // acosec(2) = 30 deg
    res = parser.evaluate("acosec(2)");
    assert(res.success);
    assert(std::abs(res.value - 30.0) < 1e-9);

    // acot(1) = 45 deg
    res = parser.evaluate("acot(1)");
    assert(res.success);
    assert(std::abs(res.value - 45.0) < 1e-9);

    // Division by zero
    res = parser.evaluate("42 / 0");
    assert(!res.success);
    assert(res.errorMessage.find("Division by zero") != std::string::npos);

    std::cout << "  ✓ Passed!" << std::endl;
}

void testProgrammerMode() {
    std::cout << "[Test] Programmer Mode (Radix & Bitset)..." << std::endl;

    calc::ProgrammerMode prog;
    prog.setValue(0x1A2B);

    assert(prog.hexString() == "1A2B");
    assert(prog.decString() == "6699");

    // Toggle bit 0 (turns 0x1A2B into 0x1A2A)
    prog.toggleBit(0);
    assert(prog.value() == 0x1A2A);

    // Word size clamp: 8-bit mode
    prog.setWordSize(calc::WordSize::Bits8);
    assert(prog.value() == 0x2A);

    std::cout << "  ✓ Passed!" << std::endl;
}

